	if !hasIDs && !hasData {
		HTTPAbortReturn(c, http.StatusOK, gin.H{HTTPReturnCode: merr.Code(merr.ErrMissingRequiredParameters), HTTPReturnMessage: "either 'ids' or 'data' must be provided"})
